import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import { DashboardSkeleton } from './DashboardSkeleton'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

async function DashboardContent() {
  const data = await getDashboardData()

  return (
    <div className="dashboard-content">
      <CardStats
        totalRevenue={data.totalRevenue}
        totalInvoices={data.totalInvoices}
      />
      <RevenueChart revenue={data.revenue} />
      <LatestInvoices invoices={data.invoices} />
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<DashboardSkeleton />}>
        <DashboardContent />
      </Suspense>
    </main>
  )
}
export function DashboardSkeleton() {
  return (
    <div
      className="dashboard-content dashboard-skeleton"
      aria-busy="true"
      aria-label="Loading dashboard data"
    >
      <div className="grid grid-cols-2 gap-4">
        <div className="card">
          <h2>Total Revenue</h2>
          <p>Loading...</p>
        </div>
        <div className="card">
          <h2>Total Invoices</h2>
          <p>Loading...</p>
        </div>
      </div>
      <div className="chart">
        <h2>Revenue</h2>
        <p>Loading revenue...</p>
      </div>
      <div className="invoices">
        <h2>Latest Invoices</h2>
        <p>Loading invoices...</p>
      </div>
    </div>
  )
}
